const fetchUser = (id) => new Promise((resolve, reject) => {
  setTimeout(() => {
    if (id > 0) {
      resolve({ id, name: `User ${id}` });
    } else {
      reject(new Error(`Nieprawidlowe id: ${id}`));
    }
  }, 1000);
});

fetchUser(1)
  .then((user) => console.log("Uzytkownik:", user))
  .catch((err) => console.error("Blad:", err.message))
  .finally(() => console.log("Zawsze wykonane"));

fetchUser(1)
  .then((user) => user.id)       // zwraca id, trafia do kolejnego then
  .then((id) => console.log("ID:", id));

Promise.all([fetchUser(1), fetchUser(2), fetchUser(3)])
  .then((users) => console.log("Wszyscy:", users.map((u) => u.name)))
  .catch((err) => console.error("Jeden zawiodl:", err.message));

