// Promise.all([...]) tworzy NOWY Promise, ktory sledzi wszystkie
// przekazane Promise naraz. Gdy KTORYKOLWIEK z nich zostanie odrzucony,
// caly Promise.all() natychmiast przechodzi w stan rejected z tym samym
// bledem - NIE czeka, az pozostale Promise "dokoncza" swoja prace w tle
// (one nadal dzialaja, ale ich ewentualne wyniki sa juz ignorowane przez
// Promise.all). Dlatego Promise.all najlepiej nadaje sie do sytuacji,
// gdzie potrzebujesz WSZYSTKICH wynikow razem, a brak jednego z nich
// i tak czyni cala operacje bezuzyteczna.

function retry(fn, proby) {
  return fn().catch((err) => {
    if (proby <= 1) throw err;
    return retry(fn, proby - 1);
  });
}
let licznik = 0;
function zawszeZawodzi() {
  licznik++;
  return Promise.reject(new Error("proba " + licznik + " nieudana"));
}
retry(zawszeZawodzi, 2).catch((err) => console.log(err.message, "licznik:", licznik));
// "proba 2 nieudana licznik: 2"

function wszystkoAlboNic(tablicaId) {
  const obietnice = tablicaId.map(
    (id) => new Promise((resolve) => setTimeout(() => resolve(id * 10), 50))
  );
  return Promise.all(obietnice);
}
wszystkoAlboNic([1, 2, 3]).then((wyniki) => console.log(wyniki));
// [10, 20, 30]

